  public function userDoc($idUser, $idDoc)
  {
  	$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
	/*******************************************Rol creador******************************************************/
	$userDocu = new UdUsuarioDocumentacion();
	$userDocu->setDocumentacionId($idDoc);
	$userDocu->setRusuariodocumentacionId(1);
	$userDocu->setUsuarioId($usuariologuiado);
	$userDocu->save();
	/*******************************************Rol Inventariador*************************************************/
	$userDocInv = new UdUsuarioDocumentacion();
	$userDocInv->setDocumentacionId($idDoc);
	$userDocInv->setRusuariodocumentacionId(2);
	$userDocInv->setUsuarioId($idUser);
	$userDocInv->save();
	/************************************************************************************************************/
  }
  
  public function userEdit($idUser, $idDoc)
  {
  	$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
	/*******************************************Rol creador******************************************************/
	$c = new Criteria();
	$c->add(UdUsuarioDocumentacionPeer::DOCUMENTACION_ID,$idDoc);
	$c->add(UdUsuarioDocumentacionPeer::RUSUARIODOCUMENTACION_ID,1);	
	$userDoc = UdUsuarioDocumentacionPeer::doSelectOne($c);
		
	$userDoc->setUsuarioId($usuariologuiado);
	$userDoc->save();
	
	/*******************************************Rol Inventariador************************************************/
	$a = new Criteria();
	$a->add(UdUsuarioDocumentacionPeer::DOCUMENTACION_ID,$idDoc);
	$a->add(UdUsuarioDocumentacionPeer::RUSUARIODOCUMENTACION_ID,2);	
	$userDocInv = UdUsuarioDocumentacionPeer::doSelectOne($a);
	
	$userDocInv->setUsuarioId($idUser);
	$userDocInv->save();
	/************************************************************************************************************/
  }
  
